# %%
import re

def parse_scores(text):
    """Extract the JSON scores object from an LLM reply, tolerating markdown
    code fences (```json ... ```) and surrounding prose. Always returns a dict."""
    if not text:
        return {}
    m = re.search(r"```(?:json)?\s*(.*?)```", text, re.DOTALL)
    candidate = m.group(1) if m else text
    try:
        return json.loads(candidate)
    except Exception:
        brace = re.search(r"\{.*\}", candidate, re.DOTALL)
        if brace:
            try:
                return json.loads(brace.group(0))
            except Exception:
                return {}
        return {}

ticket = tickets[0]
rubric_str = json.dumps(strict_rubric, indent=2)

prompt = f"""You are an expert airline customer service evaluator. Score this AI-drafted reply on the provided rubric.

Customer Question: {ticket['question']}

AI Reply: {ticket['ai_reply']}

Rubric:
{rubric_str}

For each criterion, assign a score (1-5) and briefly explain why. Format as JSON:
{{
  "relevance": {{"score": <int>, "reasoning": "<text>"}},
  "correctness": {{"score": <int>, "reasoning": "<text>"}},
  "helpfulness": {{"score": <int>, "reasoning": "<text>"}},
  "empathy": {{"score": <int>, "reasoning": "<text>"}}
}}"""

