# %% [markdown]
# ## Step 7 — Compare Verdicts: Pass/Fail Threshold
#
# Define a pass/fail rule: average score must be >= 4.0. Now compare the verdict under strict vs. lenient rubrics.

# %%
import statistics

def compute_verdict(score_dict, threshold=4.0):
    values = [data['score'] for data in score_dict.values()]
    if not values:
        return "N/A", 0.0
    avg = statistics.mean(values)
    return "PASS" if avg >= threshold else "FAIL", round(avg, 2)

strict_verdict, strict_avg = compute_verdict(scores)
lenient_verdict, lenient_avg = compute_verdict(lenient_scores)

print(f"Ticket {ticket['id']}: {ticket['question'][:50]}...\n")
print(f"  STRICT RUBRIC:  avg={strict_avg:.2f} → {strict_verdict}")
print(f"  LENIENT RUBRIC: avg={lenient_avg:.2f} → {lenient_verdict}")
print(f"\n  ⚠️  Notice: Same AI reply, different rubric = different approval decision!")

